/bin/bash -lc "python3 - <<'PY'
import ast,json,subprocess,hashlib
from pathlib import Path
p=json.loads(Path('proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
w=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','workspace://w-001']))
def validate(x,s,path='study'):
    typ=s.get('type')
    if typ=='object':
        assert isinstance(x,dict),path
        assert set(s.get('required',[]))<=set(x),path
        if s.get('additionalProperties') is False: assert set(x)<=set(s.get('properties',{})),path
        for k,v in x.items():
            if k in s.get('properties',{}): validate(v,s['properties'][k],path+'.'+k)
    elif typ=='array':
        assert isinstance(x,list) and len(x)>=s.get('minItems',0),path
        for i,v in enumerate(x):validate(v,s['items'],path+f'[{i}]')
    elif typ=='string':assert isinstance(x,str) and len(x)>=s.get('minLength',0),path
    if 'const' in s:assert x==s['const'],path
    if 'enum' in s:assert x in s['enum'],path
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert len({v['name'] for v in p['variants']})==4
assert len({v['file'] for v in p['variants']})==4
assert any(v['role']=='candidate' for v in p['variants'])
asts=[]
for v in p['variants']:
    text=Path(v['file']).read_text(); compile(text,v['file'],'exec'); tree=ast.parse(text)
    cfg=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
    assert ast.literal_eval(cfg.value)==v['config']
    cls=next(n for n in tree.body if isinstance(n,ast.ClassDef)); init=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
    defaults={a.arg:ast.literal_eval(d) for a,d in zip(init.args.args[-len(init.args.defaults):],init.args.defaults)}
    for k,val in v['config'].items():assert json.loads(json.dumps(defaults[k]))==val,(v['name'],k,defaults.get(k),val)
    for n in ast.walk(tree):
        if isinstance(n,ast.Import):assert all(a.name.split('.')[0] in {'torch','unirank'} for a in n.names)
        if isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in {'torch','unirank'}
        if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','compile','__import__','input'}
    cfg.value=ast.parse('CONFIG = {}').body[0].value
    for arg,default in zip(init.args.args[-len(init.args.defaults):],init.args.defaults):
        if arg.arg in {'context_conditioning','block_aux_adapter_context_grad'}:default.value=None
    asts.append(ast.dump(tree,include_attributes=False))
assert len(set(asts))==1,'Cells differ beyond the two factors'
ancestor=ast.parse(Path('history_g0_r0053_empirical_transfer_bridge.py').read_text())
a_methods={n.name:n for c in ancestor.body if isinstance(c,ast.ClassDef) for n in c.body if isinstance(n,ast.FunctionDef)}
now=ast.parse(Path('candidate.py').read_text())
n_methods={n.name:n for c in now.body if isinstance(c,ast.ClassDef) for n in c.body if isinstance(n,ast.FunctionDef)}
assert set(a_methods)==set(n_methods)
for name in a_methods:
    if name not in {'__init__','_context_history_correction'}:assert ast.dump(a_methods[name])==ast.dump(n_methods[name]),name
# All learned nn constructors and their AST order are identical to the empirical ancestor.
def constructors(t):return [ast.dump(n,include_attributes=False) for n in ast.walk(t) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='nn']
assert constructors(ancestor)==constructors(now)
for a in w['available_ancestor_sources']:
    assert hashlib.sha256(Path(a['file']).read_bytes()).hexdigest()==a['source_sha256'],a['file']
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()==w['available_ancestor_sources'][0]['source_sha256']
print('PASS study schema, authorized references, 4 variant CONFIG/default/syntax consistency, factor-only AST differences, inherited methods, learned constructor order, allowed imports/no direct I/O, 8 read-only source digests')
print('Native host tensor/device/data/gradient/training/parameter-count checks remain unexecuted.')
PY"

